-- Rifts World Book 19: Australia, batch 2: the gear. 73 new rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local  apps/character-creator/db/add-australia-gear.sql
--   node scripts/d1-apply.mjs --remote apps/character-creator/db/add-australia-gear.sql
--
-- WHAT IS HERE (apps/character-creator/docs/surveys/australia.md, batch 2):
--
--   Outback kit                printed 195        4 rows
--   flame throwers             printed 197        3 rows (small, medium, heavy)
--   boomerangs, spear, woomera printed 197-198    8 rows
--   air-powered crossbows      printed 198        3 rows
--   Tech-City weapons          printed 198-205   20 rows (4 S.D.C., 16 M.D.)
--   Mokoloi Techno-Wizard gear printed 142-145    5 rows (4 weapons, 1 armor)
--   Tech-City armor            printed 207-209    9 rows (8 armors, the riot shield)
--   homespun armor             printed 206-207   21 rows (12 S.D.C., 9 M.D.C.)
--
-- ALL ARE NEW: catalog-diff --table gear --remote, 2026-10-01, matched none.
-- The catalog's Boomerang, Short Spear and Long Spear are other books' rows
-- and are not touched; the spear here is named Outback Spear.
--
-- A RANGE IS STORED BY ITS LOW END. cost, weight_lbs, sdc and mdc hold the low
-- figure of a printed range; cost_note and the description give the whole
-- range. Prices are Australian dollars, which the book (printed 195) sets
-- equal to credits.
--
-- THE HOMESPUN ARMORS ARE A PRICE LIST, imported as rows on Nate's decision of
-- 2026-10-01 (the survey, Decisions 3). Each name carries "Homespun Armor:".
--
-- READ OFF RENDERS, because the text layer interleaves the columns or the ink
-- is damaged: the SMG-30 and WA-30 stat blocks (cache p200), the A-50's
-- nickname "Icer" (cache p204), the M-21's weight (cache p205), the light
-- boomerang's 1D8 (cache p198) and the homespun price list (cache p207).
-- FOUR HOMESPUN PRICES ARE PRINTED WITH THE HYPHEN LOST ($2004300 for
-- $200-$300); each cost_note says so. One, the Wooden/Leather Shield at $385,
-- cannot be told from a damaged range and is stored as printed.
--
-- TWO FIGURES THE BOOK PRINTS ODDLY, stored as printed and noted in the row:
-- the M-21 weighs "35 lb. (29.3 kg)", and one M.D.C. homespun armor gives its
-- protection as S.D.C. 50-80.
--
-- Pure ASCII, LF. Re-running it is a no-op.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('outback-firestarter', 'Firestarter', 'rifts', 'gear', NULL, 40, '$40-$80.', NULL, 0, NULL, '1D4x10+10 uses', NULL, NULL, NULL, NULL, 'Any safe fire-lighting device for the dry bush: a cube of fuel jelly, a heat-element lighter or a covered spark gun.', 'Rifts World Book 19: Australia p.195'),
('snakebite-kit', 'Snakebite Kit', 'rifts', 'gear', NULL, 480, '$480 new; $350 to refresh the drugs, $110 to refresh the bandages and antiseptic.', NULL, 0, NULL, 'One dose each of snake and spider antivenom', NULL, NULL, NULL, NULL, 'A zip pouch with a syringe, two vials of antivenom (one for any snake, one for any spider), a bandage, cleaning swabs and an identification chart. Cleans the wound and slows the poison; the victim still needs a medical facility.', 'Rifts World Book 19: Australia p.195'),
('silt-goggles', 'Silt Goggles', 'rifts', 'gear', NULL, 60, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Mesh-filter goggles with no lenses. Keep out dust and sand and cut glare without sealing in the eyes, so they can be worn indefinitely.', 'Rifts World Book 19: Australia p.195'),
('billy', 'Billy', 'rifts', 'gear', NULL, 12, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A large tin with a carry handle, for carrying and boiling water, cooking, eating from and packing delicate objects. No Outbacker is without one.', 'Rifts World Book 19: Australia p.195'),
('outback-flame-thrower-small', 'Outback Flame Thrower (Small)', 'rifts', 'weapon', NULL, 400, '$400; a new fuel canister $40.', '4D6 S.D.C.', 0, 'Cone 30 ft long', '20 shots in a weapon-mounted canister', NULL, NULL, NULL, NULL, 'A stock or homespun flame thrower. The cone can be sprayed like a burst. If the fuel canister (5 M.D.C.) is damaged past that, the percentage chance of an explosion equals the damage done: one shot of damage to the user and to everything within 2 ft per shot left in the payload.', 'Rifts World Book 19: Australia p.197'),
('outback-flame-thrower-medium', 'Outback Flame Thrower (Medium)', 'rifts', 'weapon', NULL, 900, '$900; a new fuel canister $90.', '6D6 S.D.C.', 0, 'Cone 60 ft long and 5 ft wide', '30 shots in a weapon-mounted canister', NULL, NULL, NULL, NULL, 'A stock or homespun flame thrower. The cone can be sprayed like a burst. If the fuel canister (5 M.D.C.) is damaged past that, the percentage chance of an explosion equals the damage done: one shot of damage to the user and to everything within 2 ft per shot left in the payload.', 'Rifts World Book 19: Australia p.197'),
('outback-flame-thrower-heavy', 'Outback Flame Thrower (Heavy)', 'rifts', 'weapon', NULL, 7000, '$7,000; a new fuel canister $500.', '2D6 M.D.', 1, 'Cone 60 ft long and 5 ft wide', '24 shots in a backpack canister of thermite plasma', NULL, NULL, NULL, NULL, 'A stock or homespun flame thrower. The cone can be sprayed like a burst. If the fuel canister (5 M.D.C.) is damaged past that, the percentage chance of an explosion equals the damage done: one shot of damage to the user and to everything within 2 ft per shot left in the payload.', 'Rifts World Book 19: Australia p.197'),
('boomerang-light', 'Light Boomerang', 'rifts', 'weapon', 1, 15, 'About $15; usually made by hand or traded.', '1D8 or 2D4 S.D.C.', 0, 'Range and rules are under W.P. Boomerang: 150 ft thrown to return, 600 ft thrown straight.', NULL, NULL, NULL, NULL, NULL, 'Under one foot long and under one pound. Can be thrown to return.', 'Rifts World Book 19: Australia p.197');

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('boomerang-average', 'Average Boomerang', 'rifts', 'weapon', 1, 28, '$28, or $35 for the returning type; usually made by hand or traded.', '2D4+2 or 1D10 S.D.C.', 0, 'Range and rules are under W.P. Boomerang: 150 ft thrown to return, 600 ft thrown straight.', NULL, NULL, NULL, NULL, NULL, 'A foot and a half long. Returns or not, depending on the style it was made in.', 'Rifts World Book 19: Australia p.197'),
('boomerang-hunting', 'Hunting Boomerang', 'rifts', 'weapon', 2, 48, 'About $48; usually made by hand or traded.', '2D6+2 S.D.C.', 0, 'Range and rules are under W.P. Boomerang: 150 ft thrown to return, 600 ft thrown straight.', NULL, NULL, NULL, NULL, NULL, 'About two feet long. Does not return when thrown.', 'Rifts World Book 19: Australia p.197'),
('boomerang-war', 'War Boomerang', 'rifts', 'weapon', 4, 65, '$65, or by trade.', '3D6 S.D.C.', 0, 'Range and rules are under W.P. Boomerang: 150 ft thrown to return, 600 ft thrown straight.', NULL, NULL, NULL, NULL, NULL, '4-5 ft long and 4-5 lbs, about the size of a long bow. Never returns.', 'Rifts World Book 19: Australia p.198'),
('boomerang-metal', 'Metal Boomerang', 'rifts', 'weapon', 2, 250, NULL, '3D6 S.D.C.', 0, 'Range and rules are under W.P. Boomerang: 150 ft thrown to return, 600 ft thrown straight.', NULL, NULL, NULL, NULL, NULL, 'A modern innovation no larger than an average boomerang, weighing close to 2 lbs. Can be thrown to return. Aboriginals will not use one.', 'Rifts World Book 19: Australia p.198'),
('boomerang-sporting', 'Sporting Boomerang', 'rifts', 'weapon', NULL, 10, '$10-$15.', '1D4 S.D.C.', 0, 'Range and rules are under W.P. Boomerang: 150 ft thrown to return, 600 ft thrown straight.', NULL, NULL, NULL, NULL, NULL, 'A plastic or ceramic reproduction made to return, for fun; a poor weapon.', 'Rifts World Book 19: Australia p.198'),
('outback-spear', 'Outback Spear', 'rifts', 'weapon', NULL, 50, '$50-$100; 30% more with a silver-plated head.', '1D6 S.D.C. plus P.S. damage bonus as a thrust or a clubbing blow, 2D6 S.D.C. thrown; add 1D6 for a trident or other large spear', 0, 'Thrown 150 ft; doubled with a woomera', NULL, NULL, NULL, NULL, NULL, 'The backbone weapon of any Aboriginal community. Every kind is available, including a wooden-forked fishing trident. Bonuses are under W.P. Spear.', 'Rifts World Book 19: Australia p.198'),
('woomera', 'Woomera', 'rifts', 'gear', NULL, 12, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A hand-held length of wood with a channel cut along it, used to fling a spear with a catapult motion. Doubles the spear''s throwing range at -1 to strike. Needs W.P. Spear.', 'Rifts World Book 19: Australia p.198'),
('air-crossbow-single', 'Air-Powered Crossbow (Single-Barrel)', 'rifts', 'weapon', 5, 300, NULL, '3D6 S.D.C.', 0, '350 ft', NULL, NULL, NULL, NULL, NULL, 'Fires bolts from a pneumatic pack; looks more like a rifle than a crossbow, and may be hand carried or vehicle mounted. Reloading takes one action per barrel; for $100 more per barrel a magazine holds three bolts per tube. The air canister is good for 50 shots and costs $120 to replace. Aborigines will not use one.', 'Rifts World Book 19: Australia p.198');

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('air-crossbow-double', 'Air-Powered Crossbow (Double-Barreled)', 'rifts', 'weapon', 8, 480, NULL, '2D6+1 S.D.C. per barrel, or 4D6+1 with both at one target', 0, '300 ft', NULL, NULL, NULL, NULL, NULL, 'Fires bolts from a pneumatic pack; looks more like a rifle than a crossbow, and may be hand carried or vehicle mounted. Reloading takes one action per barrel; for $100 more per barrel a magazine holds three bolts per tube. The air canister is good for 50 shots and costs $120 to replace. Aborigines will not use one.', 'Rifts World Book 19: Australia p.198'),
('air-crossbow-quad', 'Air-Powered Crossbow (Quad-Barrel)', 'rifts', 'weapon', 12, 1000, NULL, '2D6+1 S.D.C. per tube, or 1D6x10 S.D.C. with all four at once', 0, '300 ft', NULL, NULL, NULL, NULL, NULL, 'Fires bolts from a pneumatic pack; looks more like a rifle than a crossbow, and may be hand carried or vehicle mounted. Reloading takes one action per barrel; for $100 more per barrel a magazine holds three bolts per tube. The air canister is good for 50 shots and costs $120 to replace. Aborigines will not use one. -2 to strike if man-portable, so it is usually found in a vehicle turret.', 'Rifts World Book 19: Australia p.198'),
('neratech-p-18', 'NeraTech 9 mm P-18 Conventional Sidearm', 'rifts', 'weapon', 1.8, 1600, '$1,600; $15 for a new clip, $2 for 18 bullets.', '2D6+2 S.D.C.', 0, '200 ft', '18 bullets to a clip', 'Standard', NULL, NULL, NULL, 'The standard gun of bodyguards and of police in low-risk posts, and the one a civilian gun owner is likely to have. +1 to strike when aimed.', 'Rifts World Book 19: Australia p.198'),
('neratech-smg-30', 'NeraTech 9 mm SMG-30 Conventional Sub-Machinegun', 'rifts', 'weapon', 3.5, 3200, '$3,200; $30 for a new clip, $5 for 30 bullets.', '4D6+2 S.D.C.', 0, '250 ft', '30 bullets to a clip', 'Standard', NULL, NULL, NULL, 'A standard sidearm of all military and police personnel; easy to maintain and reliable. No bonuses.', 'Rifts World Book 19: Australia p.199'),
('neratech-wa-30', 'NeraTech WA-30 Conventional Assault Rifle', 'rifts', 'weapon', 9, 6800, '$6,800; $65 for a new clip, $10 for 30 bullets.', '6D6 S.D.C.', 0, '1,450 ft', '30 bullets to a clip', 'Standard', NULL, NULL, NULL, 'The hard-ammo weapon of choice for higher-risk work and raids on Outback communities. +1 to strike when aimed and in burst mode.', 'Rifts World Book 19: Australia p.199'),
('neratech-lo-20', 'NeraTech LO-20 Conventional Hunting Rifle', 'rifts', 'weapon', 8, 8400, '$8,400; $40 for a new clip, $30 for 32 bullets.', '1D4x10 S.D.C.', 0, '1,800 ft', '8 bullets to a clip', 'Single shot only; each shot is one melee attack', NULL, NULL, NULL, 'A bolt-action sporting rifle with high stopping power, also used by the TRG for light sniping. +1 to strike when aimed.', 'Rifts World Book 19: Australia p.199-200'),
('ata-super-10-shotgun', 'ATA "Super 10" Shotgun', 'rifts', 'weapon', 8, 19950, '$19,950; $1 per S.D.C. shell, $200 for an eight-shot M.D. EIPP cartridge.', '6D6 S.D.C. or 5D6 M.D.; with either round a 01-50% chance of knocking a target of up to 300 lbs off his feet (loses initiative and one melee attack)', 1, '60 ft at its most effective, up to 100 ft', '8 shells in an internal magazine, all of one type', 'Each blast is one melee action', NULL, NULL, NULL, 'Also called the Doorbuster. An EIPP shotgun firing a tight cluster; a favorite of bodyguards and Police. +1 to strike within 60 ft.', 'Rifts World Book 19: Australia p.200'),
('neratech-light-energy-pistol', 'NeraTech Light Energy Pistol', 'rifts', 'weapon', 1, 21500, '$21,500; $5,500 for a new E-clip, $2,600 to recharge.', '1D6 M.D. or 1D6+2 M.D.; two settings', 1, '1,000 ft', '18 shots per E-clip', 'Standard', NULL, NULL, NULL, 'A well-balanced laser pistol, standard military issue; civilians rarely get a permit. +2 to strike when aimed.', 'Rifts World Book 19: Australia p.200');

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('neratech-m-01', 'NeraTech M-01 Military and Police Sidearm', 'rifts', 'weapon', 2.5, 25000, '$25,000; $5,500 for a new E-clip, $2,600 to recharge.', '1D6+2 M.D. or 2D6+3 M.D.; two settings', 1, '1,000 ft', 'Fifteen 2D6+3 shots to a clip', 'Standard', NULL, NULL, NULL, 'A higher-powered version of the Light Energy Pistol, issued to heavy-duty TRG teams and senior military personnel. +1 to strike when aimed.', 'Rifts World Book 19: Australia p.201'),
('neratech-i-20-mankiller', 'NeraTech I-20 "Mankiller" Ion Pistol', 'rifts', 'weapon', 3.5, 52500, '$52,500; $5,500 for a new E-clip, $2,600 to recharge. Outback raiders will pay or trade up to $130,000 for one.', '4D6 H.P./S.D.C. to living targets, ignoring up to 90 M.D.C. of armor', 0, '500 ft', '30 shots to an E-clip', 'Single shot; each blast is one melee attack', NULL, NULL, NULL, 'A low-powered ion pistol that passes through hard armor (not power armor, robots or cyborg armor) and burns the person inside, without harming clothing, windows or vehicles. A called shot of 15 or higher instead disrupts electronics behind the armor: -1 to combat rolls and -10% to skills using them until repaired, cumulative. Restricted to Police and Military, with a few exceptions.', 'Rifts World Book 19: Australia p.201-202'),
('ata-003-boom-boom', 'ATA 003 "Boom-Boom" Hard Ammo Sidearm', 'rifts', 'weapon', 4.5, 32000, '$32,000; $4,500 for a new E-clip, $25 per EIPP slug.', '4D6 M.D.', 1, '300 ft', '5 slugs fully loaded; 30 charges in the E-clip', 'One shot per action, and one action to reload each slug', NULL, NULL, NULL, 'A civilian-legal EIPP handgun, very loud, reloaded by a breech action. Needs a P.S. of 15 to fire one-handed without bracing.', 'Rifts World Book 19: Australia p.201'),
('neratech-pn-50-splattergun', 'NeraTech Pn-50 "SplatterGun"', 'rifts', 'weapon', 1.8, 2500, '$2,500; a clip of paint $40, sleep agent $1,200, acid $2,700, toxin or nerve gas $20,500. A new air module $50, or $10 to refill. Anti-nerve serum $1,200+ per injection.', 'By pellet. Acid: 4D6 S.D.C. or 2D6 M.D. in a one-yard radius. Sleep agent: save vs non-lethal poison (16) or sleep within 1D4 melee rounds for 1D4+2 minutes per pellet. Toxin or nerve gas: save vs lethal poison (12) or convulsions, 1D6x10 to Hit Points (1D4x10 M.D. to a Mega-Damage creature) and 2D4+4 minutes unconscious; 1D6+1 on a save', 1, '60 ft', '18 pellets to a clip', 'Standard, including bursts', NULL, NULL, NULL, 'A pneumatic paint-ball gun that fires acid, sleep agent, toxin, nerve gas or paint with little damage to surroundings. Gas clouds are one yard in radius per pellet. Environmental armor protects against the sleep agent and the gas.', 'Rifts World Book 19: Australia p.202'),
('ata-p-2-10-popper', 'ATA P-2/10 "Popper" High-Powered Derringer', 'rifts', 'weapon', 0.5, 6600, '$6,600; $600 for a new battery, $10 for a slug.', '1D4 M.D.; beyond 20 ft, one M.D. or 100 S.D.C.', 1, 'Accurate to 20 ft; the bullet may travel up to 100 ft', '1 bullet; 20 shots per battery', 'Once before reloading', NULL, NULL, NULL, 'A civilian-legal EIPP derringer the size of a pen flashlight, easily palmed or kept up a sleeve. +1 to strike within 20 ft, -3 beyond.', 'Rifts World Book 19: Australia p.202'),
('ata-p-20-20-plasma-sidearm', 'ATA P-20/20 Plasma Sidearm', 'rifts', 'weapon', 4.8, 27000, '$27,000; $5,500 for a new E-clip, or $2,600 to recharge.', '4D6 M.D.', 1, '1,000 ft', '12 shots to a clip', 'Standard', NULL, NULL, NULL, 'The heaviest ATA handgun, restricted to Police and Military use outside city limits. Heavy and not very accurate.', 'Rifts World Book 19: Australia p.202'),
('ata-pinpoint-needler', 'ATA "Pinpoint" Needler Handgun', 'rifts', 'weapon', 2, 19500, '$19,500; $400 for a new clip, $1,200 if drugged; a new battery $900.', 'Low power: 1D4 S.D.C., and can deliver a drug (4D6 S.D.C., or 1D6 on a save vs harmful drugs) or a sleep agent. High power: 1D4 M.D., and can deliver a drug or toxin to an M.D. creature', 1, '250 ft', '30 needles to a clip; 100 shots to a battery', 'Standard', NULL, NULL, NULL, 'An EIPP needle gun with two settings. At high power the needle goes through M.D. armor and delivers its cargo beneath. +1 to strike when aimed.', 'Rifts World Book 19: Australia p.202-203'),
('ata-a-50-icer', 'ATA A-50 "Icer" Energy-Arc Thrower', 'rifts', 'weapon', 11, 32500, '$32,500; $5,500 for an E-clip, $12,000 for a long E-clip.', '3D6 M.D.', 1, '600 ft', '10 shots from an E-clip, 20 with a long clip', 'Standard', NULL, NULL, NULL, 'A laser ionizes a path for a high-voltage charge: a lightning-bolt effect that is loud, obvious and not very accurate. +2 to strike within 100 ft, -2 beyond.', 'Rifts World Book 19: Australia p.203');

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('ata-20k-taser', 'ATA "20K" 20,000 Volt Taser', 'rifts', 'weapon', 1, 7000, '$7,000; $5,500 for a new E-clip or battery.', '1D4 S.D.C. and save vs pain (14) or be stunned 2D4 minutes; on a save the victim loses 1D4 melee actions and combat bonuses are halved. The Police and Military grade also does 2D6 to Hit Points/S.D.C. and needs 16 to save', 0, '10 ft; contact versions are melee weapons', '30 charges to an E-clip', 'Standard; the wires take one melee action to reel in after a miss', NULL, NULL, NULL, 'Two trailing wires carry the charge. Civilian versions cannot be adjusted. No effect on a target in environmental body armor or on M.D. creatures.', 'Rifts World Book 19: Australia p.203'),
('neratech-fletcher-12', 'NeraTech "Fletcher 12" Light Rail Gun', 'rifts', 'weapon', 12, 54000, '$54,000; $6,500 for a new ammo drum.', '3D6 M.D. per single round', 1, '2,000 ft', '20 shots per ammo clip, or 100 per drum (10 lbs)', 'Standard', NULL, NULL, NULL, 'A very small rail gun braced against the hip, firing single slugs at half the usual noise. Can be ground or vehicle mounted. Needs a P.S. of 15, or the user takes 1D4 S.D.C. per shot regardless of armor.', 'Rifts World Book 19: Australia p.204'),
('neratech-bushcutter', 'NeraTech "Bushcutter" Rail Gun', 'rifts', 'weapon', 24, 110000, '$110,000; $2,000 for a mini-clip, $8,000 for a belt, $24,000 for a drum.', '4D6 M.D. per burst of 12 rounds', 1, '3,000 ft', '120-round mini-clip (10 bursts), 360-round belt (30 bursts) or 1,440-round drum (120 bursts)', 'Bursts of 12 rounds only; each burst is one melee attack', NULL, NULL, NULL, 'The typical rail gun of door gunners and bush troops. Ammunition adds 15-40 lbs. Needs a P.S. of 22, or a bipod mount.', 'Rifts World Book 19: Australia p.204'),
('neratech-m-21', 'NeraTech M-21 Heavy Particle Beam Cannon', 'rifts', 'weapon', 35, 295000, '$295,000; $48,000 for a new E-pack, $12,500 to recharge it.', '1D6x10 M.D. on a strike roll of 17 or less that hits; 2D4x10 M.D. on 18 or more', 1, '2,000 ft', '30 shots to a backpack unit; cannot use E-clips', 'Twice per melee round; each shot is one melee attack', NULL, NULL, NULL, 'The heaviest personal weapon of the City military: shoulder mounted, with a backpack power supply. Needs a P.S. of 18, otherwise -2 to strike even when aimed. The weight is printed as 35 lb. (29.3 kg), which do not agree; the pounds are stored.', 'Rifts World Book 19: Australia p.204-205'),
('ata-p-20-50-sniper-rifle', 'ATA P-20/50 Variable Frequency Sniper Rifle', 'rifts', 'weapon', 9, 57000, '$57,000; $5,500 for a standard E-clip, $10,000 for a long one.', 'Three settings: 4D6 M.D., 3D6 M.D. or 1D6x10 S.D.C.', 1, '3,000 ft', '12 shots per standard E-clip, 24 with a long E-clip', 'Each shot is one melee attack', NULL, NULL, NULL, 'Restricted to the TRG and special military teams. Collapses into a case in about one melee round (1D4+2 if unskilled), with a bipod, scopes and recoil compensation. After a full melee round it can be tuned to do full damage to laser-resistant armor, and a passive targeting laser can find the frequency without firing. +1 to strike when aimed.', 'Rifts World Book 19: Australia p.205'),
('ata-mega-20-shotgun', 'ATA "Mega-20" Shotgun', 'rifts', 'weapon', 11, 43000, '$43,000; $25 per slug, $3,000 for a new battery.', '1D4x10 M.D., or 1D6x10 S.D.C. with the battery disengaged', 1, '80 ft', '10 slugs in an internal magazine; 50 shots per battery', 'Two shots per melee round maximum', NULL, NULL, NULL, 'A rare EIPP shotgun. Needs a P.S. of 15 to brace, otherwise the user takes 1D4 S.D.C. from recoil. No bonuses.', 'Rifts World Book 19: Australia p.205'),
('mokoloi-constrictor-web-gun', 'Mokoloi Arl Wrl Kirn "Constrictor" Web Gun', 'rifts', 'weapon', 15, 48000, 'Exclusive to the Mokoloi; no Australian knows how to reload it. 48,000+ credits in North America.', 'Fires Magic Nets equal to a 5th level spell', 0, '300 ft', 'Up to eight Magic Nets; 7 P.P.E. per net to reload', 'Each shot is one melee action', NULL, NULL, NULL, 'A Techno-Wizard weapon styled as a sub-machinegun with eight barrels, used to subdue or capture. +2 to strike. Weighs 15-20 lbs. To create: 55 P.P.E., Energy Bolt, Energy Field and Magic Net, a crystal worth 300 credits or more, about 70 hours.', 'Rifts World Book 19: Australia p.142'),
('mokoloi-knuckle-dusters', 'Mokoloi Mok Karkra "Knuckle Dusters"', 'rifts', 'weapon', 1, 150000, 'Exclusive to the Mokoloi; no Australian knows how to reload it. 150,000+ credits in North America.', 'Triple energy blast: 3D6 S.D.C. or 3D6 M.D. Lightblades: 3D6 M.D.', 1, 'Blasts 1,200 ft; the Lightblades reach 3 ft', '20 blasts, or 30 minutes as Lightblades (one blast per 90 seconds)', 'Each triple blast is one melee attack; the Lightblades stay out up to three minutes per activation', NULL, NULL, NULL, 'A Techno-Wizard weapon strapped to the back of the hand, firing three energy bolts or forming three Lightblades on a mental command. +1 to strike at range, +2 in hand to hand. To create: 120 P.P.E., Globe of Daylight, Energy Field, Energy Bolt and Lightblade, three diamonds worth 1,000 credits or more each, about 110 hours.', 'Rifts World Book 19: Australia p.142-143');

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('mokoloi-chatra-lava-gun', 'Mokoloi "Chatra" Lava Gun', 'rifts', 'weapon', 160, 90000, 'Exclusive to the Mokoloi; no Australian knows how to reload it. 90,000+ credits in North America.', '4D6 M.D. to the target and 1D4 M.D. splatter to everything within 5 ft; as a bludgeon 1D6 M.D. plus Supernatural P.S. punch damage', 1, '1,000 ft', '10 goop balls in a bulb loaded like a clip, or 22 P.P.E. or 45 I.S.P. to create them in the gun', 'One shot per melee action, or a burst of four counting as two attacks (roll 1D4 for how many hit)', NULL, NULL, NULL, 'The standard Techno-Wizard weapon of Mokoloi troops, hurling a ball of burning goop. Needs a Supernatural P.S. of 13 (20+ ordinary), or 18 (26 ordinary) to fire one-handed. +1 to strike within 50 ft. Printed weight 160 lb (72 kg). To create: 98 P.P.E., Telekinesis, Barrage, Energy Bolt, Energy Field and an unknown Mokoloi element, a yellow quartz worth 60 credits or more, about 60 hours.', 'Rifts World Book 19: Australia p.143'),
('mokoloi-warriors-blade', 'Mokoloi Maa Rohk Cra "Warrior''s Blade"', 'rifts', 'weapon', 15, 20000, 'Exclusive to the Mokoloi, but a few are in Outback hands, won in combat. Valued at 20,000-30,000.', '2D6+3 M.D.', 1, 'Melee; thrown up to 600 ft at a visible target', NULL, 'Throwing is one melee attack and the return is another', NULL, NULL, 300, 'The weapon every Mokoloi male earns in a rite of maturity, for stabbing, cutting and sawing; it returns after it is thrown, hit or miss. 3-4 ft long, 15-20 lbs. +1 to strike thrown, +2 to strike and parry in melee. 300 M.D.C., harmed only by attacks aimed at it, at half damage. To create: 80 P.P.E., Wind Rush, Energy Field, Ricochet Strike and Power Weapon, silver and six diamonds worth 300 credits or more each, about 80 hours.', 'Rifts World Book 19: Australia p.143-144'),
('mokoloi-snake-back-armor', 'Mokoloi "Snake Back" Wrap Armor', 'rifts', 'armor', NULL, 30000, '$30,000-$40,000 for one can; fakes are sold at $20,000-$30,000. Rare.', NULL, 1, NULL, NULL, NULL, NULL, NULL, 60, 'A Techno-Wizard fluid sprayed from a metal tube that wraps the whole body in a nearly invisible second skin within 1D4 melee rounds. 1D4x10+50 M.D.C. (60-90), stored at the low end. Energy blasts, magic blasts and extreme heat do half damage. No mobility penalty; no protection against gas. Lasts 36 hours or until the M.D.C. is gone. A Mokoloi soldier carries 1D4 cans. To create: 28 P.P.E., about one hour.', 'Rifts World Book 19: Australia p.144-145'),
('base-4-armored-clothing', 'Base-4 Armored Clothing', 'rifts', 'armor', 10, 10000, '$10,000 per set in the Tech-Cities, two to three times that in the Outback.', NULL, 1, NULL, NULL, NULL, NULL, NULL, 8, 'An ordinary-looking suit, dress, coat, fatigues or jump suit of Base-4 fabric, as police jump suits, flight suits and undercover clothing. 8-12 M.D.C., not environmental; 10-12 lbs. -2% to climb and -5% to prowl, swim and acrobatics. M.D. explosives and projectiles also do 1D4 S.D.C. to the wearer per 12 M.D. and knock him down.', 'Rifts World Book 19: Australia p.207-208'),
('mdc-armored-trench-coat', 'M.D.C. Armored Trench Coat', 'rifts', 'armor', 17, 15000, '$15,000 in the Tech-Cities, two to three times that in the Outback.', NULL, 1, NULL, NULL, NULL, NULL, NULL, 25, 'A Base-4 long coat with padding and M.D.C. plates, popular with City Traders; a helmet (30-50 M.D.C.) comes standard and Base-4 clothing may be worn under it. Not environmental. 17-20 lbs. -10% mobility for civilians, -5% for trained personnel.', 'Rifts World Book 19: Australia p.208'),
('mdc-light-anti-assassin-vest', 'M.D.C. Light Anti-Assassin Vest', 'rifts', 'armor', 5, 6000, '$6,000 in the Tech-Cities, two times that in the Outback.', NULL, 1, NULL, NULL, NULL, NULL, NULL, 15, 'A low-profile padded vest that hides under a shirt, found only on close inspection. Protects the upper torso only; not environmental. No mobility penalty.', 'Rifts World Book 19: Australia p.208'),
('mdc-flak-vest', 'M.D.C. Flak Vest', 'rifts', 'armor', 15, 15000, '$15,000 in the Tech-Cities, two times that in the Outback.', NULL, 1, NULL, NULL, NULL, 12, NULL, 30, 'A Base-4 vest with alloy or ceramic plates covering chest, stomach and groin; standard for helicopter gunners and patrol boat crews. Comes with a helmet (30-50 M.D.C.). Torso only: a strike roll of 13 or higher hits an exposed limb. Not environmental. -5% to physical skills for civilians only.', 'Rifts World Book 19: Australia p.208'),
('police-mdc-armored-jump-suit', 'Police M.D.C. Armored Jump Suit', 'rifts', 'armor', 15, 25000, '$25,000 in the Tech-Cities, two to three times that in the Outback.', NULL, 1, NULL, NULL, NULL, NULL, NULL, 35, 'The City Police uniform of Melbourne and Perth: a padded Base-4 jump suit and boots with M.D.C. plates. M.D.C. by location: main body 35, arms 22 each, legs 28 each, head 28 with the light helmet or 50 with the full helmet, which seals the suit and makes it environmental. -5% to physical skills.', 'Rifts World Book 19: Australia p.208');

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('police-trg-riot-armor', 'Police & TRG M.D.C. Riot Armor', 'rifts', 'armor', 20, 28000, '$28,000 in the Tech-Cities, two to three times that in the Outback.', NULL, 1, NULL, NULL, NULL, NULL, NULL, 55, 'Medium environmental armor for City Police and the TRG: the police uniform with a heavy flak vest and added plating, and a multi-optic helmet. M.D.C. by location: main body 55, helmet 50, arms 22 each, legs 32 each. -5% to climb and -10% to other physical skills.', 'Rifts World Book 19: Australia p.208-209'),
('police-riot-shield', 'Police Riot Shield', 'rifts', 'armor', NULL, 10000, NULL, '1D6 S.D.C. as a blunt weapon', 1, NULL, NULL, NULL, NULL, NULL, 40, 'The optional shield issued with Police and TRG riot armor, used to butt, push and strike.', 'Rifts World Book 19: Australia p.208'),
('special-ops-heavy-combat-armor', 'Special Ops Heavy Combat Armor', 'rifts', 'armor', 28, 125000, 'Not available to the public; military use only. $125,000-$180,000+ in the Outback.', NULL, 1, NULL, NULL, NULL, NULL, NULL, 115, 'Heavy environmental plate of light M.D.C. alloys, ceramics and Base-4. M.D.C. by location: main body 115, arms 60 each, legs 75 each, light headgear 30 (not environmental), heavy helmet 70. -10% to climb and -25% to other physical skills.', 'Rifts World Book 19: Australia p.209'),
('trencher-body-armor', '"Trencher" Body Armor', 'rifts', 'armor', 23, 75000, 'Not available to the public; military use only. $75,000-$130,000+ in the Outback.', NULL, 1, NULL, NULL, NULL, NULL, NULL, 70, 'The fully sealed medium environmental armor of the City military and the TRG, with a cooling system and a one-hour oxygen supply, in matte camouflage. M.D.C. by location: main body 70, arms 40 each, legs 60 each, light headgear 30 (not environmental), heavy helmet 60. -5% to climb and -10% to other physical skills.', 'Rifts World Book 19: Australia p.209'),
('homespun-quilted-cloth', 'Homespun Armor: Quilted Cloth', 'rifts', 'armor', NULL, 100, '$100-$200.', NULL, 0, NULL, NULL, NULL, 7, 10, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 10-15.', 'Rifts World Book 19: Australia p.206'),
('homespun-quilted-leather', 'Homespun Armor: Quilted Leather', 'rifts', 'armor', NULL, 200, '$200-$300, printed with the hyphen lost.', NULL, 0, NULL, NULL, NULL, 10, 20, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 20-25.', 'Rifts World Book 19: Australia p.206'),
('homespun-quilted-cloth-with-wood', 'Homespun Armor: Quilted Cloth with Wood', 'rifts', 'armor', NULL, 275, '$275-$400.', NULL, 0, NULL, NULL, NULL, 11, 25, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 25-30.', 'Rifts World Book 19: Australia p.206'),
('homespun-quilted-cloth-or-leather-with-metal', 'Homespun Armor: Quilted Cloth or Leather with Metal', 'rifts', 'armor', NULL, 400, '$400-$500.', NULL, 0, NULL, NULL, NULL, 12, 30, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 30-35.', 'Rifts World Book 19: Australia p.206');

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('homespun-leather-with-rubber', 'Homespun Armor: Leather with Rubber (tires)', 'rifts', 'armor', NULL, 550, '$550-$700.', NULL, 0, NULL, NULL, NULL, 12, 35, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 35-40.', 'Rifts World Book 19: Australia p.206'),
('homespun-leather-with-inserts', 'Homespun Armor: Leather with Metal, Chain Mail or Ceramic Inserts or Studs', 'rifts', 'armor', NULL, 650, '$650-$800.', NULL, 0, NULL, NULL, NULL, 13, 40, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 40-50.', 'Rifts World Book 19: Australia p.206'),
('homespun-chain-mail', 'Homespun Armor: Metal, Traditional Chain Mail', 'rifts', 'armor', NULL, 700, '$700-$900.', NULL, 0, NULL, NULL, NULL, 14, 40, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 40-50.', 'Rifts World Book 19: Australia p.206'),
('homespun-chain-mail-with-leather-and-rubber', 'Homespun Armor: Metal or Chain Mail with Leather and Rubber', 'rifts', 'armor', NULL, 600, '$600-$900.', NULL, 0, NULL, NULL, NULL, 15, 60, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 60-100.', 'Rifts World Book 19: Australia p.206'),
('homespun-scale-or-splint-mail', 'Homespun Armor: Metal Scale or Splint Mail', 'rifts', 'armor', NULL, 800, '$800-$1,000.', NULL, 0, NULL, NULL, NULL, 16, 80, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 80-130.', 'Rifts World Book 19: Australia p.206'),
('homespun-metal-full-suit', 'Homespun Armor: Metal: Full Suit', 'rifts', 'armor', NULL, 900, '$900-$1,500, printed with the hyphen lost.', NULL, 0, NULL, NULL, NULL, 17, 80, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 80-200.', 'Rifts World Book 19: Australia p.206'),
('homespun-metal-shield', 'Homespun Armor: Metal Shield', 'rifts', 'armor', NULL, 200, '$200-$400, printed with the hyphen lost.', NULL, 0, NULL, NULL, NULL, NULL, 30, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 30-50.', 'Rifts World Book 19: Australia p.206'),
('homespun-wooden-leather-shield', 'Homespun Armor: Wooden/Leather Shield', 'rifts', 'armor', NULL, 385, 'Printed as $385. The two rows above it print a range with its hyphen lost, so this may be a damaged range too; stored as printed.', NULL, 0, NULL, NULL, NULL, NULL, 30, NULL, 'Homespun Outback armor. A range is stored by its low end. S.D.C. 30.', 'Rifts World Book 19: Australia p.206');

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('homespun-heavy-duty-ballistic-cloth', 'Homespun Armor: Heavy-Duty Ballistic Cloth', 'rifts', 'armor', NULL, 5000, '$5,000+.', NULL, 1, NULL, NULL, NULL, 14, NULL, 10, 'Homespun Outback armor. A range is stored by its low end. Not environmental. Most homespun armor is -10% to -15% to climb and -15% to -20% to prowl, swim and other physical skills. M.D.C. 10-12.', 'Rifts World Book 19: Australia p.207'),
('homespun-pre-rifts-bullet-proof-vest', 'Homespun Armor: Pre-Rifts Bullet-Proof Vest', 'rifts', 'armor', NULL, 10000, '$10,000+.', NULL, 1, NULL, NULL, NULL, 15, NULL, 25, 'Homespun Outback armor. A range is stored by its low end. Not environmental. Most homespun armor is -10% to -15% to climb and -15% to -20% to prowl, swim and other physical skills. M.D.C. 25.', 'Rifts World Book 19: Australia p.207'),
('homespun-pre-rifts-light-body-armor', 'Homespun Armor: Pre-Rifts Light Body Armor', 'rifts', 'armor', NULL, 15000, '$15,000+.', NULL, 1, NULL, NULL, NULL, 16, NULL, 30, 'Homespun Outback armor. A range is stored by its low end. Not environmental. Most homespun armor is -10% to -15% to climb and -15% to -20% to prowl, swim and other physical skills. M.D.C. 30-35.', 'Rifts World Book 19: Australia p.207'),
('homespun-salvaged-md-body-armor', 'Homespun Armor: Salvaged M.D. Body Armor with M.D.C. Rubber or other M.D.C. Materials', 'rifts', 'armor', NULL, 20000, '$20,000+.', NULL, 1, NULL, NULL, NULL, 16, NULL, 35, 'Homespun Outback armor. A range is stored by its low end. Not environmental. Most homespun armor is -10% to -15% to climb and -15% to -20% to prowl, swim and other physical skills. M.D.C. 35-60.', 'Rifts World Book 19: Australia p.207'),
('homespun-mdc-chain-mail-with-leather-and-rubber', 'Homespun Armor: M.D.C. Metal or Chain Mail with Leather and M.D.C. Rubber', 'rifts', 'armor', NULL, 30000, '$30,000 to $50,000+.', NULL, 1, NULL, NULL, NULL, 16, NULL, 50, 'Homespun Outback armor. A range is stored by its low end. Not environmental. Most homespun armor is -10% to -15% to climb and -15% to -20% to prowl, swim and other physical skills. M.D.C. 50-80. The book prints this figure as S.D.C. 50-80 inside its M.D.C. list; it is stored as M.D.C.', 'Rifts World Book 19: Australia p.207'),
('homespun-mdc-metal-chain-mail-or-ceramic', 'Homespun Armor: M.D.C. Metal, M.D.C. Chain Mail or Ceramic', 'rifts', 'armor', NULL, 40000, '$40,000 to $55,000+.', NULL, 1, NULL, NULL, NULL, 18, NULL, 60, 'Homespun Outback armor. A range is stored by its low end. Not environmental. Most homespun armor is -10% to -15% to climb and -15% to -20% to prowl, swim and other physical skills. M.D.C. 60-90.', 'Rifts World Book 19: Australia p.207'),
('homespun-mdc-metal-alloy-armor', 'Homespun Armor: M.D.C. Metal Alloy Armor', 'rifts', 'armor', NULL, 50000, '$50,000 to $100,000.', NULL, 1, NULL, NULL, NULL, 17, NULL, 60, 'Homespun Outback armor. A range is stored by its low end. Not environmental. Most homespun armor is -10% to -15% to climb and -15% to -20% to prowl, swim and other physical skills. M.D.C. 60-100. A piecemeal mix of salvaged high-tech armor, vehicle alloys and other M.D.C. material.', 'Rifts World Book 19: Australia p.207'),
('homespun-mdc-composite-animal-armor', 'Homespun Armor: M.D.C. Composite Animal Armor', 'rifts', 'armor', NULL, 30000, '$30,000-$60,000, printed with the hyphen lost.', NULL, 1, NULL, NULL, NULL, 14, NULL, 45, 'Homespun Outback armor. A range is stored by its low end. Not environmental. Most homespun armor is -10% to -15% to climb and -15% to -20% to prowl, swim and other physical skills. M.D.C. 45-80. Nicknamed All Natural: hide, bone, tusks and plates of Mega-Damage creatures such as the Razorback, Giant Kang and Sand Fiend. A.R. is 13+1D4, stored at its low end.', 'Rifts World Book 19: Australia p.207');

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('homespun-mdc-alloy-shield', 'Homespun Armor: M.D.C. Alloy Shield', 'rifts', 'armor', NULL, 10000, '$10,000+.', NULL, 1, NULL, NULL, NULL, NULL, NULL, 25, 'Homespun Outback armor. A range is stored by its low end. Not environmental. Most homespun armor is -10% to -15% to climb and -15% to -20% to prowl, swim and other physical skills. M.D.C. 25-40.', 'Rifts World Book 19: Australia p.207');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 73 Australia gear rows are in' AS assertion, count(*) AS got, 73 AS want
  FROM gear WHERE source_book LIKE 'Rifts World Book 19: Australia p.%';
SELECT 'category armor holds 31 of them' AS assertion, count(*) AS got, 31 AS want
  FROM gear WHERE source_book LIKE 'Rifts World Book 19: Australia p.%' AND category = 'armor';
SELECT 'category gear holds 5 of them' AS assertion, count(*) AS got, 5 AS want
  FROM gear WHERE source_book LIKE 'Rifts World Book 19: Australia p.%' AND category = 'gear';
SELECT 'category weapon holds 37 of them' AS assertion, count(*) AS got, 37 AS want
  FROM gear WHERE source_book LIKE 'Rifts World Book 19: Australia p.%' AND category = 'weapon';
SELECT 'the 21 homespun armors are in' AS assertion, count(*) AS got, 21 AS want
  FROM gear WHERE slug LIKE 'homespun-%' AND name LIKE 'Homespun Armor: %' AND source_book IN ('Rifts World Book 19: Australia p.206', 'Rifts World Book 19: Australia p.207');
SELECT 'the Icer and the M-21 hold the rendered figures' AS assertion, count(*) AS got, 2 AS want
  FROM gear WHERE (slug = 'ata-a-50-icer' AND weight_lbs = 11 AND cost = 32500) OR (slug = 'neratech-m-21' AND weight_lbs = 35 AND cost = 295000);

